/*
I = A
        B = I + A
        where
        A: ℝ ^ (2 × 2): a matrix
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<DT, 2, 2> I;
    Eigen::Matrix<DT, 2, 2> B;

    heartlib(const Eigen::Matrix<double, 2, 2> & A)
    {

        // I = A
        I = A;
        // B = I + A
        B = I + A;
    }
};

